INSERT INTO `wa_cms_lang` (`id_cms`, `id_lang`, `id_shop`, `meta_title`, `head_seo_title`, `meta_description`, `meta_keywords`, `content`, `link_rewrite`) VALUES (1, 1, 1, 'Consegna', '', 'I nostri termini e condizioni di consegna', 'condizioni, consegna, ritardo, spedizione, pacco', '<h2>Spedizioni e resi</h2>\r\n<h3>La spedizione del vostro pacco</h3>\r\n<p>I pacchi sono generalmente inviati entro 2 giorni dal ricevimento del pagamento e vengono spediti tramite UPS con tracciatura e consegna senza firma. Se preferite una consegna con UPS Extra con richiesta di firma, verrà applicato un costo aggiuntivo, quindi vi preghiamo di contattarci prima di scegliere questo metodo. Qualsiasi tipo di spedizione scegliate, vi forniremo un link per tracciare il vostro pacco online.</p>\r\n<p>Le spese di spedizione comprendono gli oneri di gestione e imballaggio e le spese postali. I costi di gestione sono fissi, mentre i costi di trasporto variano a seconda del peso totale della spedizione. Vi consigliamo di raggruppare i vostri articoli in un unico ordine. Non ci è possibile raggruppare due ordini distinti effettuati separatamente, pertanto le spese di spedizione saranno addebitate per ognuno di essi. Il vostro pacco sarà inviato a vostro rischio, ma viene prestata un\'attenzione particolare in caso di oggetti fragili.<br /><br />Le scatole hanno dimensioni adeguatamente ampie e i vostri articoli son ben protetti.</p>', 'consegna');
INSERT INTO `wa_cms_lang` (`id_cms`, `id_lang`, `id_shop`, `meta_title`, `head_seo_title`, `meta_description`, `meta_keywords`, `content`, `link_rewrite`) VALUES (1, 2, 1, 'Shipping', '', 'I nostri termini e condizioni di consegna', 'condizioni, consegna, ritardo, spedizione, pacco', '<h2>Spedizioni e resi</h2>\r\n<h3>La spedizione del vostro pacco</h3>\r\n<p>I pacchi sono generalmente inviati entro 2 giorni dal ricevimento del pagamento e vengono spediti tramite UPS con tracciatura e consegna senza firma. Se preferite una consegna con UPS Extra con richiesta di firma, verrà applicato un costo aggiuntivo, quindi vi preghiamo di contattarci prima di scegliere questo metodo. Qualsiasi tipo di spedizione scegliate, vi forniremo un link per tracciare il vostro pacco online.</p>\r\n<p>Le spese di spedizione comprendono gli oneri di gestione e imballaggio e le spese postali. I costi di gestione sono fissi, mentre i costi di trasporto variano a seconda del peso totale della spedizione. Vi consigliamo di raggruppare i vostri articoli in un unico ordine. Non ci è possibile raggruppare due ordini distinti effettuati separatamente, pertanto le spese di spedizione saranno addebitate per ognuno di essi. Il vostro pacco sarà inviato a vostro rischio, ma viene prestata un\'attenzione particolare in caso di oggetti fragili.<br /><br />Le scatole hanno dimensioni adeguatamente ampie e i vostri articoli son ben protetti.</p>', 'shipping');
INSERT INTO `wa_cms_lang` (`id_cms`, `id_lang`, `id_shop`, `meta_title`, `head_seo_title`, `meta_description`, `meta_keywords`, `content`, `link_rewrite`) VALUES (2, 1, 1, 'Note legali', '', 'Note legali', 'note, legali, crediti', '<h2>Note legali</h2>\r\n<h3>Crediti</h3>\r\n<p>Ideazione e realizzazione:</p>\r\n<p>Questo negozio online è stato creato usando <a href=\"http://www.prestashop.com\">il software PrestaShop Shopping Cart</a>. Visitate il blog di e-commerce di PrestaShop <a href=\"http://www.prestashop.com/blog/en/\"></a> per avere notizie e consigli su come vendere online e gestire il vostro sito web di e-commerce.</p>', 'note-legali');
INSERT INTO `wa_cms_lang` (`id_cms`, `id_lang`, `id_shop`, `meta_title`, `head_seo_title`, `meta_description`, `meta_keywords`, `content`, `link_rewrite`) VALUES (2, 2, 1, 'Legal notes', '', 'Terms and conditions', 'note, legali, crediti', '<h2>Note legali</h2>\r\n<h3>Crediti</h3>\r\n<p>Ideazione e realizzazione:</p>\r\n<p>Questo negozio online è stato creato usando <a href=\"http://www.prestashop.com\">il software PrestaShop Shopping Cart</a>. Visitate il blog di e-commerce di PrestaShop <a href=\"http://www.prestashop.com/blog/en/\"></a> per avere notizie e consigli su come vendere online e gestire il vostro sito web di e-commerce.</p>', 'legal-notes');
